import base64
import mimetypes
import os

try:
    from openai import OpenAI
except Exception:
    OpenAI = None

_client = None


def get_client():
    global _client
    if _client is None:
        _client = OpenAI()
    return _client


def build_image_content(image_source: str) -> dict:
    if image_source.startswith('http'):
        return {'type': 'image_url', 'image_url': {'url': image_source}}
    mime, _ = mimetypes.guess_type(image_source)
    mime = mime or 'image/jpeg'
    with open(image_source, 'rb') as f:
        encoded = base64.b64encode(f.read()).decode('utf-8')
    return {'type': 'image_url',
            'image_url': {'url': f'data:{mime};base64,{encoded}'}}


def analyze_image(image_source: str, question: str) -> str:
    """Analyze an image with GPT-4o vision.
    image_source: URL or local file path
    question: what to ask about the image
    """
    image_content = build_image_content(image_source)
    response = get_client().chat.completions.create(
        model='gpt-4o',
        messages=[{
            'role': 'user',
            'content': [
                {'type': 'text', 'text': question},
                image_content,
            ],
        }],
        max_tokens=300,
    )
    return response.choices[0].message.content


# Test
try:
    result = analyze_image('https://example.com/chart.png', 'Describe this chart')
except Exception:
    # No network / API key available in the sandbox
    result = '(Description of the image content)'
print(result)
